# ---- what they come to -----------------------------------------------------------
stat, spread, span, clear = chain.stat, chain.spread, chain.span, chain.clear
TABLES = {"RUN": RUN, "GATE": GATE}


def is_lit(row):
    return row[1] in (LIT, LITFIT)


def cells(table, w, kind, row, draw):
    """A run's cell for each of the five networks, with no scale: from the files before
    this one, which hold the same runs, but for the four rows of the budget on the first
    thousand images, which no mode before this one ran and this file holds."""
    core, way, images = row
    if is_lit(row):
        return lit.cells(table, w, kind, row, draw)
    if core in ("format", "budget"):
        return fitted.cells(table, w, kind, row, draw)
    if images == ALL:
        return bud.cells(table, w, kind, (core, bud.DARK), draw)
    return TABLES[table][w][kind][row + (draw,)]


def each_run(table, w, kind, row):
    """A table's cell for each of a row's 25 runs, network by network and then draw by draw."""
    return [cells(table, w, kind, row, d)[n] for n in range(SEEDS) for d in DRAWS]


def scaled(w, kind, row):
    """The scale's figures for each of a row's 25 runs, in the same order."""
    return [SCALE[w][kind][row + (d,)][n] for n in range(SEEDS) for d in DRAWS]


def scale(w, kind, row):
    """A row's scale over its runs: fixed on the held-out images, a mean, the least and the
    most; the test images' own, a mean; and the most the two differ by in a run."""
    got = scaled(w, kind, row)
    s = [c[SC] for c in got]
    return (sum(s) / len(s), min(s), max(s), sum(c[BEST] for c in got) / len(got),
            max(abs(c[SC] - c[BEST]) for c in got))


def error(w, kind, row, with_scale=False):
    """A row's error against its declared format over its runs, percent, with no scale or
    with it: its rms over the reference's rms, over the largest the reference is, and its
    largest over that, each a mean; and the runs within 1.0%, 1.0% and 2.0% on the three."""
    got = ([c[SC_RMS:SC_MAXFS + 1] for c in scaled(w, kind, row)] if with_scale else
           [c[:3] for c in each_run("GATE", w, kind, row)])
    means = tuple(100 * sum(c[n] for c in got) / len(got) for n in range(3))
    within = tuple(sum(100 * c[n] <= bar for c in got) for n, bar in ((0, GATE_RMS), (1, GATE_RMS), (2, GATE_MAX)))
    return means + within


def best(w, kind, row):
    """What the test images' own scale leaves of the rms error over the reference's rms,
    percent, a mean over the row's runs."""
    got = scaled(w, kind, row)
    return 100 * sum(c[BEST_RMS] for c in got) / len(got)


def agreement(w, kind, row):
    """How often the class is the declared reference's, percent, over the row's runs: with no
    scale, a mean and the runs at 99.5% or more; with the scale, a mean, the runs at 99.5% or
    more, and the least of any run."""
    plain = [c[DECLARED_CLASS] for c in each_run("RUN", w, kind, row)]
    with_it = [c[SC_AGREE] for c in scaled(w, kind, row)]
    return (sum(plain) / len(plain), sum(x >= GATE_CLASS for x in plain), sum(with_it) / len(with_it),
            sum(x >= GATE_CLASS for x in with_it), min(with_it))


def bought(w, kind, row):
    """What the scale buys a row: its rms error over the reference's rms with no scale less
    that with it, run for run and then a mean, percent of the reference's rms."""
    a, b = each_run("GATE", w, kind, row), scaled(w, kind, row)
    return 100 * sum(x[0] - y[SC_RMS] for x, y in zip(a, b)) / len(a)


def gain_share(w, kind, row):
    """The share of a row's squared error the scale takes off: one less the square of the
    ratio of its mean rms with the scale to its mean rms with none."""
    return 1 - (error(w, kind, row, True)[0] / error(w, kind, row)[0]) ** 2


def every(what, rows, kinds=KINDS):
    return span([what(w, k, row) for row in rows for w in WORKLOADS for k in kinds])


def total(what, row, n=None):
    """A count over the three data sets and both kinds: 150 runs."""
    return sum(what(w, k, row) if n is None else what(w, k, row)[n] for w in WORKLOADS for k in KINDS)


def section(title):
    print(f"\n{title}\n{'-' * len(title)}")


def label(row):
    return NAME[row[0]] + WAY[row[1]] + (", a thousand" if row[2] == FEW else "")


def three(what, kind=REFERENCE, fmt="{:.2f}"):
    return ", ".join(fmt.format(what(w, kind)) for w in WORKLOADS[:2]) + " and " + fmt.format(what(WORKLOADS[2], kind))


