def has_crosstalk(row):
    return row[0] in ("xtalk", "less_shot", "budget")


def rms(row, with_scale=False):
    return lambda w, k: error(w, k, row, with_scale)[0]


def fs(row, with_scale=False):
    return lambda w, k: error(w, k, row, with_scale)[1]


def big(row, with_scale=False):
    return lambda w, k: error(w, k, row, with_scale)[2]


def runs_within(row, n, with_scale=True):
    """The runs of a row within the gate's bar on one of the three, over the three data sets
    and both kinds: of 150."""
    return sum(error(w, k, row, with_scale)[3 + n] for w in WORKLOADS for k in KINDS)


def over_format(row, with_scale=False):
    """What a row adds over the format alone on the same images, squares for squares, percent
    of the reference's rms, as pta_board_budget.py's share is: the root of the mean, over its
    25 runs, of its rms squared less the format alone's of the same network and draw; with the
    scale, both with it."""
    other = ("format", TRAIN, row[2])

    def runs(w, k, r):
        return [c[SC_RMS] for c in scaled(w, k, r)] if with_scale else [c[0] for c in each_run("GATE", w, k, r)]

    def f(w, k):
        got = [a * a - b * b for a, b in zip(runs(w, k, row), runs(w, k, other))]
        mean = sum(got) / len(got)
        return 100 * math.copysign(math.sqrt(abs(mean)), mean)
    return f


def leaves_more(w, kind, row):
    """How much more of the rms error over the reference's rms the fixed scale leaves than
    the test images' own, percent, the most in any of a row's runs."""
    return 100 * max(c[SC_RMS] - c[BEST_RMS] for c in scaled(w, kind, row))


def from_probe(row):
    """The scale less what the probe's gain against the host's network says it is, run for
    run, over the three data sets and both kinds: one and the format alone's gain over one
    and the row's.  The probe ran on 10,000 images, at training's range."""
    light = bud.LIT if row[1] == LIT else bud.DARK
    out = []
    for w in WORKLOADS:
        for k in KINDS:
            for c, g, gf in zip(scaled(w, k, row), bud.probe(w, k, (row[0], light)), bud.probe(w, k, ("format", bud.DARK))):
                out.append(c[SC] - (1 + gf[0]) / (1 + g[0]))
    return out


def class_moves(rows=ROWS):
    """The most the class with the scale differs from the class with none, a row's mean, in
    points, over the rows, data sets and kinds."""
    return max(abs(agreement(w, k, row)[2] - agreement(w, k, row)[0]) for row in rows for w in WORKLOADS for k in KINDS)


def bigger_by(row):
    """The largest error with the scale over that with none, a row's means, for each data set
    and kind."""
    return [error(w, k, row, True)[2] / error(w, k, row)[2] for w in WORKLOADS for k in KINDS]


